// # a loop variable over a frame-resident LOCAL container: the local's storage
// # outlives the suspension, so the lend is sound -- observed by mutating on the
// # first pass over `box` and reading the mutation back on the second. The
// # container is filled by `append` rather than written as `[a, b]` because the
// # literal form does not compile at a reference instantiation
// # (BUGS.md#generic-array-literal-of-references).
// def via_local[T](items: list[T]) -> Iterator[T]:
//     box: list[T] = []
//     for src in items:
//         box.append(src)  # tpyc: warning(/may copy T into owned storage/)
//     for first in box:
//         yield first  # tpyc: ok                                            # -> S_RESUME_0
//     for again in box:
//         yield again                                                        # -> S_RESUME_1
template <typename T>
std::expected<::tpy::yield_slot_t<T>, ::tpy::StopIteration> __gen_via_local<T>::__next__() {
    while (true) switch (__state) {
    case S_INITIAL: {  // entry
        __state = S_DONE;  // until a yield sets where to resume
        box.emplace(std::vector<T>{});
        auto& __obj_0 = items;
        auto __beg_0 = __obj_0.begin();
        auto __end_0 = __obj_0.end();
        for (; __beg_0 != __end_0; ++__beg_0) {
            auto&& src = *__beg_0;
            (*box).push_back(src);
        }
        auto& __for_obj_0 = (*box);
        __for_it_0.emplace((__for_obj_0).begin());
        __for_end_0.emplace((__for_obj_0).end());
        __state = S_JOIN_0;
        continue;
    }
    case S_RESUME_0:  // after: yield first  # tpyc: ok
    case S_JOIN_0: {
        if ((*__for_it_0) == (*__for_end_0)) {
            auto& __for_obj_1 = (*box);
            __for_it_1.emplace((__for_obj_1).begin());
            __for_end_1.emplace((__for_obj_1).end());
            __state = S_JOIN_1;
            continue;
        }
        first = &(*((*__for_it_0))++);
        __state = S_RESUME_0;
        return (*first);
    }
    case S_RESUME_1:  // after: yield again
    case S_JOIN_1: {
        if ((*__for_it_1) == (*__for_end_1)) {
            __state = S_DONE;
            return ::tpy::make_unexpected(::tpy::StopIteration{});
        }
        again = &(*((*__for_it_1))++);
        __state = S_RESUME_1;
        return (*again);
    }
    case S_DONE: return ::tpy::make_unexpected(::tpy::StopIteration{});
    }
    __builtin_unreachable();
}


