// # an overload set over an `Fn` param: a lambda argument makes the call take the
// # Regime-C path, which analyzes the lambda body in a rolled-back TRIAL
// @dispatch
// def app[A, B](f: Fn[[A], B], x: A) -> B:
//     return f(x)
template<typename A, typename B, typename __F0>
  requires requires(__F0& __fn, ::tpy::param_val_or_ref_t<A> __a0) {
      { __fn(__a0) } -> std::convertible_to<B>;
  }
::tpy::val_or_ref_t<B> app(__F0&& f, ::tpy::param_val_or_ref_t<A> x) {
    return f(x);
}
// @dispatch
// def app[A, B](f: Fn[[A], B], x: list[A]) -> B:
//     return f(x[0])
template<typename A, typename B, typename __F0>
  requires requires(__F0& __fn, ::tpy::param_val_or_ref_t<A> __a0) {
      { __fn(__a0) } -> std::convertible_to<B>;
  }
::tpy::val_or_ref_t<B> app(__F0&& f, const std::vector<A>& x) {
    return f(::tpy::__getitem__(x, 0));
}

